{* Code generated by packages/kit-compose/src/server-organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
    Source: packages/compose-gen/specs/organisms/kanban-board.json
    Work items in lanes. Each lane has a title, a count and its cards; a card has a title, an optional tag and the person it belongs to. Axes: card (simple, detail: tag and person), cols (2, 3), tone, density. Moving a card between lanes is a port contract.
    Props (p): id, title, lanes, empty, cards, countLabel, card, cols, tone, density, landmarkLabel. *}
{var $v_id = ($p['id'] ?? null)}
{var $v_title = ($p['title'] ?? null)}
{var $v_lanes = ($p['lanes'] ?? null)}
{var $v_empty = ($p['empty'] ?? '')}
{var $v_cards = ($p['cards'] ?? null)}
{var $v_countLabel = ($p['countLabel'] ?? null)}
{var $v_card = ($p['card'] ?? 'detail')}
{var $v_cols = ($p['cols'] ?? '3')}
{var $v_tone = ($p['tone'] ?? 'default')}
{var $v_density = ($p['density'] ?? 'default')}
{var $v_landmarkLabel = ($p['landmarkLabel'] ?? null)}
{capture $c_12}
  {if og_t(og_eq(og_len($v_lanes), 0))}
    {=og_include('blocks/empty-state.latte', ['p' => ['icon' => 'kanban', 'title' => $v_empty]])|noescape}
  {else}
    {capture $c_11}
      {foreach og_l($v_lanes) as $v_lane}
        {capture $c_10}
          {capture $c_3}
            {capture $c_1}
              {=og_text(og_get($v_lane, ['title']))}
            {/capture}
            {=og_include('compose/Title.latte', ['as' => 3, 'size' => 'base', 'weight' => 'bold', 'children' => (string) $c_1])|noescape}
            {capture $c_2}
              {=og_text(og_tpl($v_countLabel, [og_len(og_where($v_cards, 'lane', og_get($v_lane, ['key'])))]))}
            {/capture}
            {=og_include('compose/Text.latte', ['size' => 'xs', 'class' => 'text-muted-foreground', 'children' => (string) $c_2])|noescape}
          {/capture}
          {=og_include('compose/Group.latte', ['gap' => '2', 'align' => 'center', 'justify' => 'between', 'children' => (string) $c_3])|noescape}
          {capture $c_9}
            {foreach og_l(og_where($v_cards, 'lane', og_get($v_lane, ['key']))) as $v_c}
              {capture $c_8}
                {capture $c_4}
                  {=og_text(og_get($v_c, ['title']))}
                {/capture}
                {=og_include('compose/Text.latte', ['size' => 'sm', 'weight' => 'semibold', 'children' => (string) $c_4])|noescape}
                {if og_t(og_eq($v_card, 'detail'))}
                  {capture $c_7}
                    {capture $c_5}
                      {=og_text(og_get($v_c, ['tag']))}
                    {/capture}
                    {=og_include('blocks/pill.latte', ['p' => ['tone' => 'blue', 'icon' => 'tag'], 'children' => og_markup($c_5)])|noescape}
                    {capture $c_6}
                      {=og_text(og_get($v_c, ['who']))}
                    {/capture}
                    {=og_include('compose/Text.latte', ['size' => 'xs', 'class' => 'text-muted-foreground', 'children' => (string) $c_6])|noescape}
                  {/capture}
                  {=og_include('compose/Group.latte', ['gap' => '2', 'align' => 'center', 'justify' => 'between', 'class' => 'flex-wrap', 'children' => (string) $c_7])|noescape}
                {/if}
              {/capture}
              {=og_include('compose/ListItem.latte', ['class' => og_s(og_cnv(['flex flex-col rounded bg-card inset-ring inset-ring-border', (og_t(og_eq($v_density, 'compact')) ? 'gap-2 p-2' : 'gap-2 p-4')])), 'attrs' => og_attrs(['data-testid', 'item']), 'children' => (string) $c_8])|noescape}
            {/foreach}
          {/capture}
          {=og_include('compose/List.latte', ['class' => 'm-0 flex list-none flex-col gap-2 p-0', 'children' => (string) $c_9])|noescape}
        {/capture}
        {=og_include('compose/Stack.latte', ['gap' => '4', 'align' => 'stretch', 'class' => 'rounded bg-muted p-4', 'attrs' => og_attrs(['data-testid', 'lane']), 'children' => (string) $c_10])|noescape}
      {/foreach}
    {/capture}
    {=og_include('compose/Grid.latte', ['cols' => og_s((og_t(og_eq($v_cols, '2')) ? '1-2' : '1-3')), 'class' => 'items-start gap-4', 'attrs' => og_attrs(['data-testid', 'lanes']), 'children' => (string) $c_11])|noescape}
  {/if}
{/capture}
{=og_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'tone' => $v_tone, 'density' => $v_density, 'landmarkLabel' => $v_landmarkLabel], 'children' => og_markup($c_12)])|noescape}
